<?php require __DIR__.'/config/bootstrap.php';$slug=$_GET['slug']??'';$st=db()->prepare("SELECT p.*,c.name category,u.name author FROM posts p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN users u ON u.id=p.author_id WHERE p.slug=? AND p.status='published' AND p.published_at<=NOW()");$st->execute([$slug]);$p=$st->fetch();if(!$p){http_response_code(404);exit('404');}$ip=$_SERVER['REMOTE_ADDR']??'';$ua=substr($_SERVER['HTTP_USER_AGENT']??'',0,255);$check=db()->prepare("SELECT id FROM post_views WHERE post_id=? AND ip_address=? AND viewed_at>DATE_SUB(NOW(),INTERVAL 30 MINUTE) LIMIT 1");$check->execute([$p['id'],$ip]);if(!$check->fetch()){$v=db()->prepare("INSERT INTO post_views(post_id,ip_address,user_agent) VALUES(?,?,?)");$v->execute([$p['id'],$ip,$ua]);db()->prepare("UPDATE posts SET view_count=view_count+1 WHERE id=?")->execute([$p['id']]);}$title=$p['seo_title']?:$p['title'];$description=$p['seo_description']?:excerpt($p['content']);require __DIR__.'/includes/header.php';?><article class="article"><div class="meta"><?=e($p['category'])?> · <?=e($p['author'])?> · <?=date('M j, Y',strtotime($p['published_at']))?> · <?=reading_time($p['content'])?> min read</div><h1><?=e($p['title'])?></h1><p class="meta"><?=number_format((int)$p['view_count']+1)?> views</p><div class="article-content"><?= $p['content'] ?></div><?php $ts=db()->prepare("SELECT t.* FROM tags t JOIN post_tags pt ON pt.tag_id=t.id WHERE pt.post_id=?");$ts->execute([$p['id']]);foreach($ts as $t)echo '<a class="btn" style="margin:4px" href="tag.php?slug='.e($t['slug']).'">#'.e($t['name']).'</a>'; ?><hr><h2>Comments</h2><?php $cs=db()->prepare("SELECT * FROM comments WHERE post_id=? AND status='approved' ORDER BY created_at DESC");$cs->execute([$p['id']]);foreach($cs as $c)echo '<div class="form"><b>'.e($c['name']).'</b><p>'.nl2br(e($c['comment'])).'</p></div>'; ?><form class="form" method="post" action="comment.php"><input type="hidden" name="post_id" value="<?=e($p['id'])?>"><?=csrf_field()?><label>Name</label><input name="name" required maxlength="100"><label>Email</label><input type="email" name="email" required maxlength="190"><label>Comment</label><textarea name="comment" required maxlength="5000"></textarea><button>Submit comment</button></form></article><?php require __DIR__.'/includes/footer.php';?>